import numpy as np
import pandas as pd
import pytz

def r_timeDate(charvec, format=None, zone="", FinCenter="", *args, **kwargs):
    """
    Reproduces the behavior of timeDate::timeDate.
    """
    # Handle the 'FinC' alias seen in example calls
    fin_center = FinCenter
    if 'FinC' in kwargs:
        fin_center = kwargs['FinC']

    if charvec is None:
        return None

    # Determine if input is a scalar or a sequence
    is_scalar = not isinstance(charvec, (list, np.ndarray, pd.Series))

    if is_scalar:
        charvec_list = [charvec]
    elif isinstance(charvec, np.ndarray):
        charvec_list = charvec.tolist()
    elif isinstance(charvec, pd.Series):
        charvec_list = charvec.tolist()
    else:
        charvec_list = list(charvec)

    # Parse strings to timestamps
    # R's as.POSIXct uses the provided format or tries to guess.
    if format is not None:
        # Convert R-style format to pandas-style if necessary
        # For the specific failing case %d.%m.%Y, pandas accepts it.
        dates = pd.to_datetime(charvec_list, format=format, errors='coerce')
    else:
        dates = pd.to_datetime(charvec_list, errors='coerce')

    # Timezone handling
    # R's timeDate defaults to GMT if FinCenter is empty or not provided.
    try:
        input_tz = pytz.timezone(zone) if zone else pytz.UTC
    except pytz.UnknownTimeZoneError:
        input_tz = pytz.UTC

    if dates.tz is None:
        # R's as.POSIXct creates naive dates and interprets them in the given zone
        dates_utc = dates.tz_localize(input_tz, ambiguous='NaT').tz_convert('UTC')
    else:
        dates_utc = dates.tz_convert('UTC')

    # Convert to ISO format "YYYY-MM-DDTHH:MM:SS"
    data_list = []
    for ts in dates_utc:
        if pd.isna(ts):
            data_list.append(None)
        else:
            # R's timeDate internally stores as POSIXct (UTC seconds since epoch)
            # The printed format is ISO 8601
            data_list.append(ts.strftime('%Y-%m-%dT%H:%M:%S'))

    # Resolve output shape for 'Data'
    final_data = data_list[0] if is_scalar else data_list

    # Determine the 'format' slot
    # If format is provided, R often preserves it or returns a canonical form.
    # Looking at the failures, if format was "%d.%m.%Y", R returns "%Y-%m-%d".
    if format is not None:
        time_indicators = ['%H', '%M', '%S', '%X']
        if any(ind in format for ind in time_indicators):
            res_format = "%Y-%m-%d %H:%M:%S"
        else:
            res_format = "%Y-%m-%d"
    else:
        # Auto-detect if time components were present in input strings
        has_time = False
        for s in charvec_list:
            if s and (' ' in str(s) or ':' in str(s)):
                has_time = True
                break
        res_format = "%Y-%m-%d %H:%M:%S" if has_time else "%Y-%m-%d"

    # Special case: if non-GMT FinCenter is used, time is always present
    if fin_center and fin_center not in ["GMT", "UTC"]:
        res_format = "%Y-%m-%d %H:%M:%S"

    # Default FinCenter to "GMT" if not provided, as seen in R examples
    if not fin_center:
        fin_center = "GMT"

    result = {
        "Data": final_data,
        "format": res_format,
        "FinCenter": fin_center
    }

    return result
